class Solution {
public:
    vector<int> findOriginalArray(vector<int>& changed) {
        int n = changed.size();
        if (n % 2 != 0) return {};
        const int MAXV = 100000;
        vector<int> count(MAXV + 1, 0);
        for (int x : changed) count[x]++;
        vector<int> result;
        result.reserve(n / 2);
        for (int v = 0; v <= MAXV; v++) {
            if (count[v] == 0) continue;
            if (v == 0) {
                if (count[0] % 2 != 0) return {};
                for (int i = 0; i < count[0] / 2; i++) result.push_back(0);
                count[0] = 0;
                continue;
            }
            int dbl = 2 * v;
            if (dbl > MAXV || count[dbl] < count[v]) return {};
            for (int i = 0; i < count[v]; i++) result.push_back(v);
            count[dbl] -= count[v];
            count[v] = 0;
        }
        return result;
    }
};
